import { Section } from "@/components/marketing/section";
import { fmt, studyFacts } from "@/content/study-facts";
import {
  CoverageRange,
  CrawlerGrid,
  ReadabilityRing,
  RenderGap,
  StudyDots,
} from "@/components/marketing/highlight-visuals";

/**
 * Dashboard-derived highlights — big, bold, left-aligned sections.
 *
 * Each section pulls a single metric from the study and pairs the
 * display-scale number with a short explanation and a small animated
 * illustration (see highlight-visuals.tsx). Numbers come from `study-facts`
 * (generated by scripts/build-study-facts.mjs, ~2 KB) — never typed by hand, and
 * never imported from the full study, so the marketing bundle stays lean
 * (docs/seo-research.md §2.4).
 */

const { coverage, blocks, verticalMedians, render } = studyFacts;

const sections = [
  {
    eyebrow: "The study",
    value: fmt(studyFacts.crawled),
    label: "homepages measured, each fetched two ways — plain HTTP versus headless Chromium, so JavaScript is the only variable.",
    source: `Seobot study · Tranco list ${studyFacts.listId} · crawled ${studyFacts.runDate}`,
    visual: <StudyDots />,
  },
  {
    eyebrow: "Readability",
    value: `${studyFacts.readablePct}%`,
    label: "of the top sites are readable as plain HTML. The rest are a wall to any crawler that does not run JavaScript.",
    source: `${fmt(studyFacts.readable)} of ${fmt(studyFacts.crawled)} sites · median AI-visible content ${coverage.median}%`,
    visual: <ReadabilityRing />,
  },
  {
    eyebrow: "Crawler access",
    value: `${Math.round(studyFacts.retrievalBlockedPct)}%`,
    label: "of sites with a robots.txt block at least one AI search crawler — on purpose or by accident, the result is the same.",
    source: `GPTBot ${blocks.GPTBot.pctOfRobotsFiles}% · ClaudeBot ${blocks.ClaudeBot.pctOfRobotsFiles}% · PerplexityBot ${blocks.PerplexityBot.pctOfRobotsFiles}% of ${fmt(studyFacts.robotsFiles)} robots.txt files`,
    visual: <CrawlerGrid />,
  },
  {
    eyebrow: "Coverage",
    value: `${coverage.median}%`,
    label: "median share of the rendered page that a non-rendering client actually receives, among the readable sites.",
    source: [
      `p25 ${coverage.p25}%`,
      `p75 ${coverage.p75}%`,
      verticalMedians.search !== null && `search engines ${verticalMedians.search}%`,
      verticalMedians.social !== null && `social ${verticalMedians.social}%`,
    ]
      .filter(Boolean)
      .join(" · "),
    visual: <CoverageRange />,
  },
  {
    eyebrow: "Structured data",
    value: fmt(render.invisibleWords),
    label: `words are completely invisible to static scrapers until JavaScript executes — across ${fmt(render.sitesCompared)} sites.`,
    source: `${fmt(render.injectedJsonLdSites)} of ${fmt(render.withMetrics)} sites declare JSON-LD only after render`,
    visual: <RenderGap />,
  },
];

export function Highlights() {
  return (
    <>
      {sections.map((section, index) => (
        <Section
          key={section.eyebrow}
          id={`highlight-${index}`}
          className="border-t border-border"
        >
          <div className="container grid items-center gap-10 lg:grid-cols-[1.15fr_1fr] lg:gap-16">
            <div className="flex flex-col gap-4">
              <span className="text-sm font-semibold tracking-tight text-primary-soft-foreground">
                {section.eyebrow}
              </span>
              <h2 className="text-left text-display-md font-black sm:text-display-lg">
                {section.value}
              </h2>
              <p className="max-w-xl text-pretty text-xl leading-relaxed text-muted-foreground sm:text-2xl">
                {section.label}
              </p>
              <p className="text-sm text-muted-foreground">{section.source}</p>
            </div>
            <div className="flex items-center justify-start lg:justify-end">
              {section.visual}
            </div>
          </div>
        </Section>
      ))}
    </>
  );
}